econPatch:
;(function (G) {
  const S = 0.56;
  const dt = G.economy.dropTable;
  for (const t of ['common', 'rare', 'boss']) {
    const d = dt[t] && dt[t].awakenMaterial;
    if (d) { d.min = Math.max(1, Math.round(d.min * S)); d.max = Math.max(d.min, Math.round(d.max * S)); }
  }
})(G);

